const entradas = $input.all();
const inferencias = $('HTTP Request').all().map(item => item.json);

return entradas.map((item, index) => {
  const contenido = item.json.output?.[0]?.content?.[0];

  if (!contenido || contenido.text == null) {
    throw new Error('No se encontro el resultado de GPT.');
  }

  const resultado = typeof contenido.text === 'string'
    ? JSON.parse(contenido.text)
    : contenido.text;

  if (!resultado || typeof resultado !== 'object') {
    throw new Error('Formato de respuesta de GPT invalido.');
  }

  const api = inferencias.find(
    dato => dato.archivo === resultado.archivo
  );

  if (!api) {
    throw new Error('No se encontro la inferencia original.');
  }

  const clasificacion = String(api.clasificacion)
    .trim()
    .toLowerCase();

  if (!['correcta', 'defectuosa'].includes(clasificacion)) {
    throw new Error('Clasificacion desconocida.');
  }

  const esDefectuosa = clasificacion === 'defectuosa';

  // Ante un valor desconocido, exigir revision.
  const revisionAPI = !(
    api.requiere_revision_humana === false ||
    api.requiere_revision_humana === 'false'
  );

  const requiereRevision = esDefectuosa || revisionAPI;

  // ResNet18 conserva la autoridad sobre la prediccion.
  resultado.archivo = api.archivo;
  resultado.clasificacion = api.clasificacion;
  resultado.confianza = Number(api.confianza);

  if (!Number.isFinite(resultado.confianza)) {
    throw new Error('Confianza del modelo invalida.');
  }

  // Regla determinista de seguridad industrial.
  resultado.requiere_revision_humana = requiereRevision;

  if (requiereRevision) {
    resultado.prioridad = 'alta';
  }

  if (esDefectuosa) {
    resultado.recomendacion =
      'Apartar la pieza para inspeccion humana. No aprobar automaticamente.';

    resultado.justificacion =
      `${resultado.justificacion || ''} ` +
      'El protocolo exige revision humana para toda pieza defectuosa.';
  }

  // Mantener la estructura que utiliza Google Sheets.
  contenido.text = resultado;

  return {
    ...item,
    pairedItem: { item: index }
  };
});

