const datos = $input.first().json;
const resultados = datos.resultados;

if (!Array.isArray(resultados) || resultados.length === 0) {
  throw new Error("No se recibieron pronósticos del GRU");
}

const lineas = resultados.map(r => ({
  linea: r.linea,
  fecha_pronostico: r.fecha_pronostico,
  gru_pct: Number(r.pronostico_gru_pct),
  promedio_movil_pct: Number(r.pronostico_promedio_movil_pct),
  modelo_seleccionado: r.modelo_seleccionado_por_validacion
}));

const mayor = lineas.reduce((a, b) =>
  a.gru_pct > b.gru_pct ? a : b
);

return [{
  json: {
    tipo: "RESUMEN_GRU",
    origen: "SIMULADO_ACADEMICO_NO_REAL",
    total_lineas: lineas.length,
    linea_mayor_pronostico: mayor.linea,
    mayor_pronostico_pct: mayor.gru_pct,
    pronosticos: lineas,
    requiere_validacion_humana: true
  }
}];

/*
 VISIONGUARD INDUSTRIAL v2.2 - INTEGRACION DE 3 MODELOS (nodo Code JS)
 ResNet18 (imagen) + GRU (serie temporal) + Transformer NLP (texto)
 Construye el RESUMEN ESTRUCTURADO que recibe el LLM (nunca la tabla cruda)
 y calcula las alertas condicionales con los umbrales de Config.
*/
const cfg = $('Config').first().json;

// Lee un nodo sin romper si no se ejecuto en esta corrida (p. ej. sin imagenes).
function leer(nodo) {
  try { return $(nodo).all().map(i => i.json); } catch (e) { return []; }
}
const esVerdadero = v => v === true || String(v ?? '').trim().toLowerCase() === 'true';
const esFalso = v => v === false || String(v ?? '').trim().toLowerCase() === 'false';

const datosResNet = leer('HTTP Request');
const imagenes = datosResNet.filter(d =>
  ['correcta', 'defectuosa'].includes(String(d.clasificacion ?? '').trim().toLowerCase()));
const erroresInferencia = datosResNet.length - imagenes.length;

// Sin imagenes validas: la rama Hay_Imagenes_Pendientes ya envio el aviso del turno.
if (imagenes.length === 0) return [];

const gru = leer('Resumen_GRU').find(d => d.tipo === 'RESUMEN_GRU');
if (!gru) throw new Error('Integracion incompleta: falta el resumen GRU (API de series).');

const nlpTf = leer('Clasificar_NLP_Python')[0] || leer('Clasificar_NLP_JS_respaldo')[0] || null;
const nlpHistorico = leer('Lectura_NLP').filter(d => d.id_caso && String(d.modulo ?? '').trim() === 'Transformer_NLP');

const umbralConf = Number(cfg.umbral_confianza ?? 0.9);
const umbralPron = Number(cfg.umbral_pronostico_pct ?? 7.5);
const umbralDisc = Number(cfg.umbral_discrepancia_pp ?? 1.5);

// 1. ResNet18 con regla de seguridad: defectuosa => revision humana
const resultadosImagenes = imagenes.map(d => {
  const clasificacion = String(d.clasificacion).trim();
  const esDefectuosa = clasificacion.toLowerCase() === 'defectuosa';
  return {
    archivo: d.archivo,
    modelo: d.modelo ?? 'ResNet18',
    clasificacion,
    confianza: Number(d.confianza),
    probabilidad_defecto: Number(d.probabilidades?.defectuosa),
    decision_sugerida: d.decision_sugerida,
    requiere_revision_humana_reportada: d.requiere_revision_humana,
    requiere_revision_humana: esDefectuosa || esVerdadero(d.requiere_revision_humana),
    aprobacion_automatica: false
  };
});

// 2. Alertas condicionales (cada una con su regla explicita)
const alertas = [];
for (const im of resultadosImagenes) {
  if (im.clasificacion.toLowerCase() === 'defectuosa')
    alertas.push({ tipo: 'PIEZA_DEFECTUOSA', detalle: `${im.archivo} clasificada Defectuosa` });
  if (Number.isFinite(im.confianza) && im.confianza < umbralConf)
    alertas.push({ tipo: 'CONFIANZA_BAJA', detalle: `${im.archivo}: confianza ${(im.confianza * 100).toFixed(2)} % < ${umbralConf * 100} %` });
  if (im.clasificacion.toLowerCase() === 'defectuosa' && esFalso(im.requiere_revision_humana_reportada))
    alertas.push({ tipo: 'INCONSISTENCIA_API', detalle: `${im.archivo}: defectuosa sin revision exigida por la API; se fuerza revision humana` });
}
for (const p of gru.pronosticos ?? []) {
  if (Number(p.gru_pct) >= umbralPron)
    alertas.push({ tipo: 'PRONOSTICO_SOBRE_UMBRAL', detalle: `Linea ${p.linea}: GRU ${p.gru_pct} % >= ${umbralPron} % (simulado)` });
  if (Math.abs(Number(p.gru_pct) - Number(p.promedio_movil_pct)) >= umbralDisc)
    alertas.push({ tipo: 'DISCREPANCIA_MODELOS_SERIE', detalle: `Linea ${p.linea}: GRU ${p.gru_pct} % vs promedio movil ${p.promedio_movil_pct} %` });
}
if (erroresInferencia > 0)
  alertas.push({ tipo: 'ERROR_INFERENCIA_IMAGEN', detalle: `${erroresInferencia} imagen(es) sin resultado valido de la API` });
if (!nlpTf || nlpTf.transformer_ejecutado !== true)
  alertas.push({ tipo: 'NLP_TRANSFORMER_NO_DISPONIBLE', detalle: nlpTf?.motivo_sin_transformer || 'Sin resultado NLP; solo reglas o sin datos' });

// 3. Resumen NLP compacto (resultados, no textos crudos)
const nlp = nlpTf ? {
  transformer_ejecutado: nlpTf.transformer_ejecutado,
  modelo: nlpTf.modelo,
  metodo: nlpTf.metodo,
  metricas_prueba: nlpTf.metricas_prueba,
  mejor_metodo_en_prueba_f1: nlpTf.mejor_metodo_en_prueba_f1,
  metodo_usado_operacion: nlpTf.metodo_usado_operacion,
  n_operacion: nlpTf.n_operacion,
  distribucion_causas_operacion: nlpTf.distribucion_causas_operacion,
  causa_principal_operacion: nlpTf.causa_principal_operacion,
  concordancia_transformer_reglas_pct: nlpTf.concordancia_transformer_reglas_pct,
  casos_operacion: (nlpTf.casos_operacion || []).slice(0, 5)
} : { transformer_ejecutado: false, causa_principal_operacion: 'sin_datos' };

return [{
  json: {
    sistema: 'VisionGuard Industrial',
    tipo: 'ANALISIS_INTEGRADO',
    origen: 'PROTOTIPO_ACADEMICO_CON_DATOS_SIMULADOS',
    modelos_integrados: ['ResNet18', 'GRU', 'Transformer_NLP'],
    resumen_integracion: {
      total_imagenes: resultadosImagenes.length,
      total_defectuosas: resultadosImagenes.filter(d => d.clasificacion.toLowerCase() === 'defectuosa').length,
      total_lineas: gru.total_lineas,
      linea_mayor_pronostico: gru.linea_mayor_pronostico,
      mayor_pronostico_pct: gru.mayor_pronostico_pct,
      total_casos_nlp: nlpHistorico.length,
      total_alertas: alertas.length
    },
    imagenes: resultadosImagenes,
    series_temporales: gru,
    nlp_transformer: nlp,
    analisis_nlp: nlpHistorico.slice(0, 5).map(d => ({
      id_caso: d.id_caso, recomendacion: d.recomendacion_original,
      accion_sugerida: d.accion_sugerida, estado: d.estado
    })),
    alertas,
    umbrales: { confianza: umbralConf, pronostico_pct: umbralPron, discrepancia_pp: umbralDisc },
    advertencias: [
      'Los datos GRU y los reportes NC son simulados con fines academicos.',
      'Los pronosticos GRU no son mediciones en tiempo real.',
      'Los reportes NC no necesariamente corresponden a las imagenes analizadas.',
      'Una clasificacion Correcta no constituye aprobacion definitiva.',
      'Toda pieza defectuosa requiere revision humana.',
      'Ninguna pieza puede aprobarse automaticamente.'
    ],
    requiere_validacion_humana: true,
    aprobacion_automatica: false,
    estado: 'PENDIENTE_VALIDACION_HUMANA'
  }
}];

/*
 VISIONGUARD INDUSTRIAL v2.2 - VALIDACION FINAL DE SEGURIDAD (nodo Code JS)

 Capas de control sobre la salida de GPT-4o mini:
  1. Parseo robusto del JSON (tolera ```json ... ```).
  2. Estructura: 11 campos obligatorios y textos no vacios.
  3. Reglas de seguridad deterministas: nunca aprobacion automatica, revision
     humana siempre, prioridad alta si hay pieza defectuosa, origen academico.
     Si el LLM las viola, se CORRIGEN al valor conservador y se registra.
  4. Anti-alucinacion numerica: toda cifra del texto del LLM debe existir en
     los datos de entrada (con tolerancia de redondeo y conversion a %).
  5. Frases de aprobacion sospechosas ("pieza aprobada" sin negacion).
 Si el JSON es inutilizable (o el nodo LLM fallo tras 3 reintentos) se genera
 un ANALISIS DETERMINISTA DE RESPALDO: el flujo no se cae en silencio y el
 correo indica la fuente del analisis.
*/
const ORIGEN = 'PROTOTIPO_ACADEMICO_CON_DATOS_SIMULADOS';
const CAMPOS = ['diagnostico', 'recomendacion', 'prioridad', 'justificacion', 'resumen_imagenes',
  'resumen_series_temporales', 'resumen_nlp', 'riesgos_limitaciones', 'requiere_revision_humana',
  'aprobacion_automatica', 'origen'];
const TEXTOS = ['diagnostico', 'recomendacion', 'justificacion', 'resumen_imagenes',
  'resumen_series_temporales', 'resumen_nlp', 'riesgos_limitaciones'];

const integracion = $('Integracion_3_Modelos').first().json;
const imagenes = integracion.imagenes ?? [];
if (imagenes.length === 0) throw new Error('No existen resultados ResNet18.');
const hayDefectuosa = imagenes.some(d => String(d.clasificacion ?? '').trim().toLowerCase() === 'defectuosa');
const gru = integracion.series_temporales ?? {};
const nlp = integracion.nlp_transformer ?? {};

const fallas = [];       // impiden usar la respuesta
const correcciones = []; // se corrigieron a valor seguro

// ---------- 1. Extraer y parsear
const r = $input.first().json;
if (r.error) fallas.push('Nodo LLM con error: ' + String(r.error.message ?? r.error).slice(0, 160));
const contenido = r.output?.[0]?.content?.find(c => c.type === 'output_text')?.text
  ?? r.output?.[0]?.content?.[0]?.text ?? r.message?.content ?? r.text ?? null;
let a = null;
if (contenido == null) fallas.push('El LLM no entrego contenido.');
else {
  try {
    a = typeof contenido === 'string'
      ? JSON.parse(contenido.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, ''))
      : contenido;
    if (!a || typeof a !== 'object' || Array.isArray(a)) { fallas.push('La respuesta no es un objeto JSON.'); a = null; }
  } catch (e) { fallas.push('JSON invalido del LLM.'); }
}

// ---------- 2. Estructura
if (a) {
  for (const c of CAMPOS) if (!(c in a)) fallas.push(`Falta el campo: ${c}`);
  for (const c of TEXTOS) if (c in a && (typeof a[c] !== 'string' || !a[c].trim())) fallas.push(`Contenido invalido: ${c}`);
}

// ---------- 3. Reglas de seguridad (corregir, no confiar)
if (a && fallas.length === 0) {
  if (!['alta', 'media', 'baja'].includes(a.prioridad)) { correcciones.push(`prioridad '${a.prioridad}' -> alta`); a.prioridad = 'alta'; }
  if (hayDefectuosa && a.prioridad !== 'alta') { correcciones.push('pieza defectuosa: prioridad -> alta'); a.prioridad = 'alta'; }
  if (a.aprobacion_automatica !== false) { correcciones.push('aprobacion_automatica -> false'); a.aprobacion_automatica = false; }
  if (a.requiere_revision_humana !== true) { correcciones.push('requiere_revision_humana -> true'); a.requiere_revision_humana = true; }
  if (a.origen !== ORIGEN) { correcciones.push('origen corregido'); a.origen = ORIGEN; }
  for (const k of Object.keys(a)) if (!CAMPOS.includes(k)) { delete a[k]; correcciones.push(`clave extra eliminada: ${k}`); }
}

// ---------- 4. Anti-alucinacion numerica
const permitidos = new Set();
const agregar = v => {
  if (!Number.isFinite(v)) return;
  [v, v * 100, v / 100].forEach(x => { permitidos.add(+x.toFixed(2)); permitidos.add(+x.toFixed(1)); permitidos.add(Math.round(x)); });
};
(function recorrer(o) {
  if (o == null) return;
  if (typeof o === 'number') agregar(o);
  else if (typeof o === 'string') (o.match(/\d+(?:[.,]\d+)?/g) || []).forEach(s => agregar(parseFloat(s.replace(',', '.'))));
  else if (typeof o === 'object') Object.values(o).forEach(recorrer);
})(integracion);
for (let i = 0; i <= 12; i++) permitidos.add(i);   // conteos y ordinales pequenos ("3 lineas", "L1")
permitidos.add(100);

let noRespaldados = [];
let frasesAprobacion = [];
if (a && fallas.length === 0) {
  const texto = TEXTOS.map(c => a[c]).join(' ');
  noRespaldados = [...new Set((texto.match(/\d+(?:[.,]\d+)?/g) || []))]
    .map(s => ({ s, v: parseFloat(s.replace(',', '.')) }))
    .filter(({ v }) => ![...permitidos].some(p => Math.abs(p - v) <= 0.011))
    .map(({ s }) => s);
  frasesAprobacion = (texto.match(/.{0,30}\baprobad[ao]s?\b/gi) || [])
    .filter(f => !/\b(no|nunca|sin|ninguna|ningun)\b|automatic|definitiv/i.test(f));
  if (noRespaldados.length || frasesAprobacion.length) {
    a.riesgos_limitaciones += ' [CONTROL AUTOMATICO: ' +
      (noRespaldados.length ? `cifras sin respaldo en los datos: ${noRespaldados.join(', ')}. ` : '') +
      (frasesAprobacion.length ? 'se detecto una frase de aprobacion sin negacion; NO hay aprobacion automatica. ' : '') +
      'Verificar contra el panel antes de decidir.]';
  }
}

// ---------- 5. Respaldo determinista
const pct = v => Number.isFinite(Number(v)) ? (Number(v) * 100).toFixed(2) + ' %' : 'n/d';
function respaldo() {
  const def = imagenes.filter(d => String(d.clasificacion).toLowerCase() === 'defectuosa');
  return {
    diagnostico: `Analisis de respaldo (sin LLM valido). ResNet18: ${imagenes.length} imagen(es), ${def.length} defectuosa(s): ` +
      imagenes.map(d => `${d.archivo} ${d.clasificacion} (${pct(d.confianza)})`).join('; ') +
      `. GRU simulado: mayor pronostico en ${gru.linea_mayor_pronostico} (${gru.mayor_pronostico_pct} %). ` +
      `NLP: causa principal de NC ${nlp.causa_principal_operacion ?? 'sin datos'}.`,
    recomendacion: def.length
      ? 'Apartar las piezas defectuosas e inspeccionarlas manualmente. No aprobar automaticamente.'
      : 'Continuar con la validacion humana segun protocolo. No aprobar automaticamente.',
    prioridad: 'alta',
    justificacion: 'Regla determinista aplicada porque la salida del LLM no supero la validacion: ' + fallas.join(' | '),
    resumen_imagenes: imagenes.map(d => `${d.archivo}: ${d.clasificacion}, ${pct(d.confianza)}`).join('; '),
    resumen_series_temporales: (gru.pronosticos ?? []).map(p => `${p.linea}: GRU ${p.gru_pct} %, promedio movil ${p.promedio_movil_pct} %`).join('; ') + ' (simulado).',
    resumen_nlp: nlp.transformer_ejecutado ? `Transformer ejecutado; causa principal ${nlp.causa_principal_operacion}.` : 'Transformer no disponible; solo reglas.',
    riesgos_limitaciones: 'Respuesta del LLM descartada por el control automatico; diagnostico generado por reglas fijas.',
    requiere_revision_humana: true, aprobacion_automatica: false, origen: ORIGEN
  };
}

const usarRespaldo = !a || fallas.length > 0;
const analisis = usarRespaldo ? respaldo() : a;
const fuente = usarRespaldo ? 'RESPALDO_DETERMINISTA' : (correcciones.length ? 'LLM_CORREGIDO' : 'LLM_VALIDADO');

return [{
  json: {
    sistema: 'VisionGuard Industrial',
    tipo: 'ANALISIS_INTEGRADO_VALIDADO',
    ...analisis,
    estado: 'PENDIENTE_VALIDACION_HUMANA',
    fuente_analisis: fuente,
    controles_seguridad: {
      json_valido: !usarRespaldo,
      fallas_llm: fallas,
      correcciones_aplicadas: correcciones,
      cifras_no_respaldadas: noRespaldados,
      frases_aprobacion_sospechosas: frasesAprobacion,
      alucinacion_sospechada: noRespaldados.length > 0 || frasesAprobacion.length > 0,
      revision_humana_obligatoria: true,
      aprobacion_automatica_bloqueada: true,
      validacion_humana_realizada: false
    },
    total_imagenes: integracion.resumen_integracion?.total_imagenes,
    total_casos_nlp: integracion.resumen_integracion?.total_casos_nlp
  }
}];

/*
 VISIONGUARD INDUSTRIAL v2.2 - PREPARAR REGISTRO INTEGRADO (nodo Code JS)
 Una fila por imagen para la pestana Analisis_Integrado.
 clave_unica = INTEGRADO|archivo|fecha_de_ejecucion -> la misma imagen no se
 registra ni se notifica dos veces el mismo dia (ver Evitar_Notificaciones_Duplicadas).
 Las columnas nuevas (v2.2) se agregan solas en Sheets.
*/
const analisis = $input.first().json;
const integracion = $('Integracion_3_Modelos').first().json;

if (analisis.tipo !== 'ANALISIS_INTEGRADO_VALIDADO') throw new Error('El analisis no ha sido validado.');
if (analisis.requiere_revision_humana !== true || analisis.aprobacion_automatica !== false ||
    analisis.controles_seguridad?.validacion_humana_realizada !== false) {
  throw new Error('Validacion de seguridad incorrecta.');
}

const imagenes = integracion.imagenes ?? [];
if (imagenes.length === 0) throw new Error('No se encontraron imagenes.');
const series = integracion.series_temporales ?? {};
if (!(series.pronosticos ?? []).length) throw new Error('No se encontraron pronosticos GRU.');
const nlp = integracion.nlp_transformer ?? {};
const ahora = $now.setZone('America/Santiago');
const alertas = integracion.alertas ?? [];

return imagenes.map(imagen => {
  const archivo = String(imagen.archivo ?? '').trim();
  if (!archivo) throw new Error('Imagen sin nombre de archivo.');
  // Alertas propias de otra imagen se excluyen; las globales (GRU, NLP) se incluyen siempre.
  const POR_IMAGEN = ['PIEZA_DEFECTUOSA', 'CONFIANZA_BAJA', 'INCONSISTENCIA_API'];
  const alertasImagen = alertas.filter(x => !POR_IMAGEN.includes(x.tipo) || String(x.detalle).includes(archivo));
  return {
    json: {
      clave_unica: ['INTEGRADO', archivo, ahora.toFormat('yyyy-MM-dd')].join('|'),
      fecha_registro: ahora.toFormat('yyyy-MM-dd HH:mm:ss'),
      archivo,
      clasificacion: imagen.clasificacion,
      confianza: Number(imagen.confianza),
      linea_mayor_pronostico: series.linea_mayor_pronostico,
      pronostico_max_pct: Number(series.mayor_pronostico_pct),
